	providers := make([]providerRecordResponse, 0, len(entries))
	for _, e := range entries {
		providers = append(providers, providerRecordResponse{
			ProviderID: e.providerID,
			Addresses:  e.addresses,
			ExpiresAt:  e.expiresAt,
		})
	}
